insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('b6a7e224-6477-5150-8c15-838d1ac05d21', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'contribution_per_unit', 'Contribution per unit', 'What one unit leaves us after every variable cost of getting it sold — the money that pays fixed costs and profit.', 'C = P_net − L − W − D − M − K', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('24e5070f-111e-582d-8a4c-2a24a561cf84', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'contribution_per_order', 'Contribution per order', 'Contribution earned on one typical order to this channel.', 'C × units per order', 'currency/order') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('96fe6e3a-1e34-5662-aee8-9dc1c2cd4300', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'contribution_per_month', 'Contribution per month', 'Contribution this play earns in a month at the realistic volume.', 'C × Q_realistic', 'currency/month') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('1e58bdf1-cb0a-5fce-9019-d974dcb26d39', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'p_net', 'Net price (P_net)', 'What we actually receive per unit after the channel takes its margin, rebate and listing fees.', 'P_net = list × (1 − channel margin − rebate) − listing fee total ÷ expected units over listing period', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('c5032698-0069-5592-905d-1213fb565560', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'list_price', 'List price', 'The price our direct customer resells at, before sales tax.', 'Shelf ÷ (1 + t), less the retailer margin when a distributor sits in between', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('5648312e-41a2-581b-9074-e4796afe00d4', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'landed_cost', 'Landed cost (L)', 'Cost of one unit sitting cleared in our warehouse in the market: product, freight, insurance, duty, clearance and any tax we cannot recover.', 'L = CIF + duty + clearance + import tax (if not recoverable)', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('667f796f-aac2-5269-b153-21807156ff0f', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'cif', 'CIF', 'Cost, insurance and freight: product price plus getting it to the destination port.', 'CIF = supplier price + origin handling + freight + insurance', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('4cf829fd-c83b-5d10-90dc-2b074339fdba', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'duty', 'Import duty', 'Customs duty charged on CIF value, at the rate for this HS code, origin and trade regime.', 'duty = CIF × duty rate', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('b6c80289-19c9-5897-a5b6-e1e9c87b8b3d', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'import_tax', 'Import tax', 'GST / SST / VAT charged at import. A cost only when we cannot claim it back.', 'import tax = (CIF + duty) × import tax rate', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('2d165744-f03a-54d2-820f-6db2dd63c99d', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'warehousing_per_unit', 'Warehousing per unit (W)', 'Storage and handling cost carried by one unit while it waits to be sold.', 'W = pallet cost/day × stock days ÷ units per pallet + handling per order ÷ units per order', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('b119e03d-9cdb-5e89-9131-f121bd0c8454', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'delivery_per_unit', 'Delivery per unit (D)', 'Cost of delivering one unit to the channel''s door or DC.', 'D = delivery cost per drop ÷ units per drop', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('00cb0796-febd-5af3-8af5-10f3086d8af3', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'marketing_per_unit', 'Marketing per unit (M)', 'Promotion, sampling and merchandising spend spread over each unit sold.', 'M (input)', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('a2fc9949-20a7-55b6-a037-5d36997c8f59', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'cash_cost_per_unit', 'Cash cost per unit (K)', 'Financing cost of the cash tied up in stock and unpaid invoices for this unit.', 'K = L × annual finance rate × (stock days + receivable days − payable days) ÷ 365', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('ac566858-d486-5be8-acdf-581ba0afdb90', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'breakeven_units', 'Break-even volume', 'Units per month needed before this channel''s fixed costs are covered.', 'Q_breakeven = F ÷ C', 'units/month') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('49543091-cad0-5dd0-8ce2-783aa7a2ea26', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'value_density', 'Value density (V)', 'Net revenue per cubic metre shipped. Low values mean freight and space will eat the margin.', 'V = P_net ÷ volume per unit (m³)', 'currency/m³') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('d6ef7a1e-e828-5eb9-87d9-7324b36732fc', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'l_max', 'Max affordable landed cost (L_max)', 'The highest landed cost we can carry and still break even at the target shelf price.', 'L_max = P_shelf ÷ (1 + t) × (1 − m_retail) × (1 − m_dist) − S', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('1b955b63-f729-5bff-bdd3-6514399cde4e', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'headroom', 'Headroom', 'How far our landed cost sits below the maximum the shelf price allows. Negative means the price does not work.', 'headroom = L_max − L', 'currency/unit') on conflict (id) do nothing;
insert into glossary (id, created_at, updated_at, created_by, key, label, meaning, formula_text, unit) values ('0d82fb20-035e-50be-996a-c63e14f34614', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', null, 'cost_to_serve', 'Cost to serve + marketing (S)', 'Everything after landing that it costs to serve the channel per unit: warehousing, delivery, financing, trade spend and marketing.', 'S = W + D + K + trade spend + M', 'currency/unit') on conflict (id) do nothing;
